        'upper-lower' => [
            'name_en' => 'Upper / Lower',
            'name_ru' => 'Верх / Низ',
            'notes' => [
                'assisted-dip' => 'Tuck elbows at a 45° angle, lean your torso forward 15°',
                'back-squat' => 'Sit back and down, 15° toe flare, drive your knees out laterally',
                'barbell-bench-press' => 'Tuck elbows at a 45° angle, squeeze your shoulder blades and stay firm on the bench',
                'barbell-bent-over-row' => 'Lean your torso over at a 45° angle, keep your lower back neutral, double overhand grip',
                'barbell-hip-thrust' => 'Tuck your chin and rib cage down, only move your hips. use a pad',
                'bicycle-crunch' => 'Focus on flexing and rotating your spine, bring your left elbow to right knee, right elbow to left knee',
                'cable-flye' => 'Keep your scapulae retracted, pull your inner elbows together (not your hands)',
                'cable-lateral-raise' => 'Lean away from the machine, arms straight out to your side',
                'cable-seated-row' => 'Use a v-bar grip, let your scapulae protract during the eccentric',
                'chest-supported-t-bar-row' => 'Retract your scapulae during the concentric, protract your scapulae during the eccentric',
                'crunch' => 'Focus on flexing your spine, don\'t yank your head with your arms',
                'deadlift' => 'Brace your lats, chest tall, hips high, pull the slack out of the bar prior to moving it off the ground',
                'dumbbell-incline-press' => 'Keep your scapulae retracted and depressed',
                'dumbbell-lateral-raise' => 'Tilt the dumbbell such that your pinky comes up first',
                'dumbbell-row' => 'Brace onto a bench for support, pull your elbow against your sides',
                'dumbbell-seated-shoulder-press' => 'Bring the dumbbell all the way down to your shoulders, keep your torso upright',
                'dumbbell-single-leg-hip-thrust' => 'Place the dumbbell on your working thigh, tuck your chin and rib cage, only move your hips',
                'dumbbell-supinated-curl' => 'Drive your pinky into the handle harder than your pointer finger',
                'dumbbell-walking-lunge' => '10 steps each leg. take medium strides, let your torso lean forward',
                'ez-bar-curl' => 'Press your pinky into the bar harder than your pointer finger',
                'goblet-squat' => 'Hold a dumbbell directly underneath your chin, sit back and down, push your knees out laterally',
                'hammer-curl' => 'Neutral grip, prevent your upper arm from moving',
                'hanging-leg-raise' => 'Focus on flexing your lower back, perform off of captain\'s chair',
                'lat-pulldown' => 'Pull your elbows straight out to your sides, use a 1.5x shoulder width grip',
                'leg-extension' => 'Focus on squeezing your quads to make the weight move',
                'leg-press' => 'Medium feet placement on the platform, don\'t allow your lower back to round',
                'lying-leg-curl' => 'Focus on squeezing your hamstrings to make the weight move',
                'machine-seated-hip-abduction' => 'Keep your butt in the seat, focus on squeezing your glutes to make the weight move',
                'military-press' => 'Squeeze your glutes to keep your torso upright, clear your head out of the way, press up and slightly back',
                'neutral-grip-pulldown' => 'Palms facing each other. pull your elbows against your sides',
                'plank' => 'Squeeze your glutes, keep your hips low',
                'reverse-grip-lat-pulldown' => 'Pull your elbows down against your sides, use shoulder width grip',
                'reverse-pec-deck' => 'Protract your scapulae, sweep the weight out and back',
                'romanian-deadlift' => 'Maintain a neutral lower back, set your hips back, don\'t allow your spine to round',
                'seated-face-pull' => 'Pull your arms back and out',
                'seated-leg-curl' => 'Focus on squeezing your hamstrings to make the weight move',
                'single-arm-cable-curl' => 'Face away from the cable you are using, keep your arm behind your torso',
                'single-arm-pulldown' => 'Start with your non-dominant arm, match reps with dominant arm',
                'single-arm-rope-tricep-extension' => 'Pull your arm behind your torso, don\'t move your upper arm',
                'single-leg-leg-extension' => 'Focus on squeezing your quads to make the weight move',
                'single-leg-lying-leg-curl' => 'Focus on squeezing your hamstrings to make the weight move',
                'standing-calf-raise' => 'Press all the way up to your toes, stretch your calves at the bottom, don’t bounce',
            ],
